parameters.text:
=Draft a bug report from the attached screenshot.

Extra context supplied with the upload:
- Environment: {{ ($json.body && $json.body.environment) || $json.environment || 'not provided' }}
- Error log / console output:
{{ ($json.body && $json.body.error_log) || $json.error_log || 'not provided' }}

Analyze the image and return the structured bug report.

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "bug_title": {
      "type": "string",
      "description": "Short, specific bug title (max 90 chars)"
    },
    "severity": {
      "type": "string",
      "enum": [
        "Critical",
        "High",
        "Medium",
        "Low"
      ]
    },
    "summary": {
      "type": "string",
      "description": "One or two sentences describing the bug"
    },
    "steps_to_reproduce": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Concrete numbered actions a tester can follow"
    },
    "expected_result": {
      "type": "string"
    },
    "actual_result": {
      "type": "string"
    },
    "visual_details": {
      "type": "string",
      "description": "Exact on-screen evidence visible in the screenshot"
    },
    "environment": {
      "type": "string"
    },
    "labels": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Optional extra labels, e.g. ui, regression, login"
    }
  },
  "required": [
    "bug_title",
    "severity",
    "summary",
    "steps_to_reproduce",
    "actual_result"
  ]
}

parameters.jsCode:
// Pull the request metadata straight from the webhook item (survives the AI Agent node).
const uploadItem = $('Webhook - Screenshot Upload').first().json || {};
const body = uploadItem.body || uploadItem;

const repoOwner = body.repo_owner || body.repoOwner || 'REPLACE_WITH_GITHUB_OWNER';
const repoName = body.repo_name || body.repoName || 'REPLACE_WITH_GITHUB_REPO';
const fallbackEnvironment = body.environment || 'Not provided';

const results = [];

for (const item of $input.all()) {
  const raw = item.json || {};

  // The Agent may return the parsed object directly, or nested under `output` (possibly as a string).
  let bug = raw.output !== undefined ? raw.output : raw;
  if (typeof bug === 'string') {
    try {
      bug = JSON.parse(bug);
    } catch (e) {
      bug = { summary: bug };
    }
  }
  if (!bug || typeof bug !== 'object') {
    bug = {};
  }

  const severity = String(bug.severity || 'Medium');

  let steps = bug.steps_to_reproduce;
  if (!Array.isArray(steps)) {
    steps = steps ? [String(steps)] : [];
  }
  if (steps.length === 0) {
    steps = ['Not determinable from the supplied screenshot.'];
  }

  const labels = Array.isArray(bug.labels) ? bug.labels.map(String) : [];
  if (!labels.includes('bug')) labels.push('bug');
  const severityLabel = 'severity:' + severity.toLowerCase().replace(/\s+/g, '-');
  if (!labels.includes(severityLabel)) labels.push(severityLabel);

  const baseTitle = bug.bug_title || bug.summary || 'Bug reported from screenshot';
  const issueTitle = ('[Bug] ' + baseTitle + ' — ' + severity).slice(0, 250);

  const issueBody = [
    '### Summary',
    bug.summary || '_No summary produced._',
    '',
    '### Steps to Reproduce',
    ...steps.map((step, i) => `${i + 1}. ${step}`),
    '',
    '### Expected Result',
    bug.expected_result || '_Not specified._',
    '',
    '### Actual Result',
    bug.actual_result || '_Not specified._',
    '',
    '### Visual Details',
    bug.visual_details || '_None reported._',
    '',
    '### Environment',
    bug.environment || fallbackEnvironment,
    '',
    '---',
    '_Reported automatically by the Screenshot-to-Bug-Reporter agent (Gemini 2.5 Flash-Lite vision analysis)._'
  ].join('\n');

  results.push({
    json: {
      repo_owner: repoOwner,
      repo_name: repoName,
      issue_title: issueTitle,
      issue_body: issueBody,
      labels: labels,
      labels_csv: labels.join(','),
      severity: severity
    }
  });
}

return results;
